diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..196596d
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,53 @@
+import { isDate } from "../dates.js";
+import { memoryStore } from "../db/store.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+/** Imports a whole CSV file atomically, skipping tickets already imported. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/).map((line, index) => ({ line, number: index + 1 })).filter(({ line }) => line.trim());
+  for (const { line, number } of lines) {
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line))
+      throw new AppError("bad_request", { reason: `row ${number}: invalid CSV` });
+  }
+  const [headerLine, ...dataLines] = lines;
+  const header = headerLine ? parseCsv(headerLine.line)[0] : [];
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (header.length !== columns.length || columns.some((c, i) => header[i].trim() !== c))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const copy = memoryStore(store.data);
+  const existing = new Set(copy.data.sales.map((s) => s.ticket));
+  const imported = new Set();
+  let dishes = 0;
+  for (const { line, number } of dataLines) {
+    const fields = parseCsv(line)[0];
+    const where = `row ${number}`;
+    const [ticket, soldAt, dishText, qtyText] = fields.map((v) => v.trim());
+    if (fields.length !== 4 || !ticket) throw new AppError("bad_request", { reason: `${where}: invalid row` });
+    if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(soldAt) || !Number.isFinite(Date.parse(soldAt)) || !isDate(soldAt.slice(0, 10)))
+      throw new AppError("bad_request", { reason: `${where}: invalid soldAt` });
+    const dishId = Number(dishText);
+    const qty = Number(qtyText);
+    if (!/^\d+$/.test(dishText) || !Number.isSafeInteger(dishId) || dishId < 1 || !/^\d+$/.test(qtyText) || !Number.isSafeInteger(qty) || qty < 1)
+      throw new AppError("bad_request", { reason: `${where}: invalid dishId or qty` });
+    let needs;
+    try {
+      needs = scaled(getRecipe(copy, getDish(copy, dishId).recipeId), qty);
+      if (!existing.has(ticket)) {
+        for (const n of needs) if (n.qty > 0) consume(copy, n.itemId, n.qty, { at: new Date(soldAt).toISOString(), ref: `sale:${ticket}` });
+      }
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `${where}: ${error.code}` });
+    }
+    if (existing.has(ticket)) continue;
+    copy.data.sales.push({ ticket, soldAt: new Date(soldAt).toISOString(), dishId, qty, ingredients: needs });
+    imported.add(ticket);
+    dishes += qty;
+  }
+  store.data = copy.data;
+  return { tickets: imported.size, dishes };
+}
